// ─────────────────────────────────────────────────────────────────────────
//  03 · thirty basis points of a payment                             ★★☆
//  concepts: 1 bps = 1/10000 · half-up integer division · net of fee
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    /** The fee in cents, half-up. */
    static long feeCents(long amountCents, int bps) {
        return (amountCents * bps + 5000) / 10000;
    }

    /** The amount minus the fee. */
    static long netOfFee(long amountCents, int bps) {
        return amountCents - feeCents(amountCents, bps);
    }

    /** The smallest charge whose net of the fee is at least netCents (0 <= bps < 10000). */
    static long grossUp(long netCents, int bps) {
        long amount = netCents * 10000 / (10000 - bps);
        while (amount > 0 && netOfFee(amount - 1, bps) >= netCents) amount--;
        while (netOfFee(amount, bps) < netCents) amount++;
        return amount;
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("30 bps of 2500 dollars is 7.50 exactly", () ->
            eq(feeCents(250000, 30), 750));
        test("25 bps of 100 dollars is 25 cents", () ->
            eq(feeCents(10000, 25), 25));
        test("a fraction of a cent rounds half up", () ->
            eq(feeCents(333, 150), 5));
        test("zero bps charges nothing (boundary)", () -> {
            eq(feeCents(250000, 0), 0);
            eq(netOfFee(250000, 0), 250000);
        });
        test("netOfFee subtracts the rounded fee", () -> {
            eq(netOfFee(250000, 30), 249250);
            eq(netOfFee(333, 150), 328);
        });
        test("gross-up finds the smallest charge that nets the target", () -> {
            eq(grossUp(249250, 30), 250000);
