// ─────────────────────────────────────────────────────────────────────────
//  06 · the round trip that moved a cent                             ★★★
//  concepts: BigDecimal.multiply · RoundingMode.HALF_EVEN · round-trip conversion drift
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;

class Exercise {

    /** amount × rate at scale 2, banker's rounding. */
    static BigDecimal convert(String amount, String rate) {
        return new BigDecimal(amount).multiply(new BigDecimal(rate)).setScale(2, RoundingMode.HALF_EVEN);
    }

    /** amount minus the converted-and-converted-back amount, at scale 2. */
    static BigDecimal roundTripLoss(String amount, String rate, String inverse) {
        var back = convert(convert(amount, rate).toPlainString(), inverse);
        return new BigDecimal(amount).subtract(back).setScale(2, RoundingMode.HALF_EVEN);
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("a tie rounds to the even neighbour 4", () -> {
