// ─────────────────────────────────────────────────────────────────────────
//  07 · who pays the odd cent                                        ★☆☆
//  concepts: integer division and remainder · last installment absorbs the remainder · exact sums
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    /** Which installment carries the cents that do not divide evenly. */
    enum Policy { FIRST, LAST }

    /** n installments; the policy says which one absorbs the remainder. */
    static long[] installments(long totalCents, int n, Policy policy) {
        long[] plan = new long[n];
        Arrays.fill(plan, totalCents / n);
        plan[policy == Policy.FIRST ? 0 : n - 1] += totalCents % n;
        return plan;
    }

    /** The last installment: the base plus the remainder. */
    static long lastInstallment(long totalCents, int n) {
        return totalCents / n + totalCents % n;
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("the last installment carries the odd cent", () ->
            eq(installments(1000, 3, Policy.LAST), new long[] {333, 333, 334}));
        test("or the first one does, by policy", () ->
