import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    /** pct% off, then offCents off. */
    static long percentThenFixed(long cents, int pct, long offCents) {
        return Math.max(0, percentOff(cents, pct) - offCents);
    }

    /** offCents off, then pct% off. */
    static long fixedThenPercent(long cents, int pct, long offCents) {
        return percentOff(Math.max(0, cents - offCents), pct);
    }

    /** How many cents more the customer pays when the fixed amount comes first. */
    static long orderGap(long cents, int pct, long offCents) {
        return fixedThenPercent(cents, pct, offCents) - percentThenFixed(cents, pct, offCents);
    }

    private static long percentOff(long cents, int pct) {
        return (cents * (100 - pct) + 50) / 100;
